# -*- coding: utf-8 -*-
"""init-группа: e2e Init по транскрипту плана 2026-10-27 (сценарии IN-1 … IN-4).

E2E проверяет систему целиком: цепочку «форма → инспектор (ручки, вопросы) → куратор (QA / confirmation / deny)
→ подтверждение → запись о сервере → рабочий запрос» по журналу и состоянию системы. Один тест — один такт:
один прогон до следующего действия пользователя; многотактовые сценарии разбиты на цепочку тестов, где начало
такта зафиксировано в тесте (вопрос узла в транскрипте), а остальное окружение — живое. Поведение отдельного узла
на фикстурах — в node-isolate (коды сценариев связывают их — SCENARIOS.md).
"""
from common import (test, STAND_I, STAND_K, cafe_ctx, CAFE_NEW_GENERIC, CAFE_NEW_WITH_ADDR, CAFE_ANSWER, CAFE_Q,
                    CAFE_SHORT, CAFE_ROLE, RECORDS, tags_short_str, form)

P = "init/e2e"

D1C = "«Сервер 1С: Бухгалтерия и ЗУП на PostgreSQL, около 12 пользователей; обслуживает франчайзи «1С-Партнёр»; бэкап — pg_dump каждую ночь в /backup/pg; apache публикует данные 1С для обмена с сайтом»"
DWEB = "«Публичный сайт компании на VPS у хостинг-провайдера: nginx, PHP, MariaDB; раз в час забирает прайс из 1С; сайт поддерживает веб-студия «Пиксель»; бэкапы сайта делает хостер»"
NOQ = "Эталон «вопросов нет» `[предл.]`: теги и полные поля пользователь не подтверждает [UC-21], вопрос не задаётся там, где поле заполняется из осмотра [M]; предусловия тегов отдельным вопросом не подтверждаются ([Q49])."

REF_1C = "Эталон записи srv-1c (полный чек-лист — `init/README.md`, «Эталонные записи»): `conn-info` ip 10.0.1.12, user evalbot; `tags` {host, 1c/cluster, db/pg, web/apache}; `short-desc` — сервер 1С, Бухгалтерия и ЗУП, PostgreSQL (< 50 слов); `tags-short-desc` — по четырём тегам (≤ 30 слов); `full-desc` — роль, пользователи, публикация, бэкап, подрядчик, ОС и ресурсы; `tags-full-desc` — host: тома, службы, порты, cron 02:00 → /backup/pg; 1c: 8.3.24, порты кластера, ИБ Buh и ZUP, учётки и роли из сканера; db: PostgreSQL 16, buh, zup; web: публикация на 8080."
REF_WEB = "Эталон записи web-01: `conn-info` ip 10.0.1.11, user evalbot; `tags` {host, web/nginx, db/mysql, unsupported:provider-hv}; `short-desc` — публичный сайт на VPS у хостера, nginx/PHP/MariaDB, прайс из 1С раз в час; `tags-short-desc` — по четырём тегам; `full-desc` — сайт, VPS у хостера, импорт прайса, подрядчик «Пиксель», бэкапы у хостера; `tags-full-desc` — web: example-trade.ru, журналы; host: задание импорта с адресом публикации 1С; db: MariaDB 10.6, site."

STATE_ADD = "`e2e-expected-state` (rule-based по журналу и состоянию системы): цепочка — инспектор (ручки ≤ 40, вопросы ≤ 10), затем куратор (QA ≤ 5, confirmation ≤ 3), затем карточка подтверждения — на подтверждение `short-desc` и `server-name` [UC-21], `tags-short-desc` показывается [UC-32]; вопросов пользователю ровно столько, сколько в эталоне; после подтверждения запись о сервере сохранена и совпадает с эталоном по полям (`insp-fields` для полей инспектора, `cur-fields` для полей куратора [AR-29]); в контексте оркестратора появились `server-name`, `conn-ip`, `conn-user`, `tags`, `short-desc` [AR-22] (design doc 2.3, 4.2; `tags-short-desc` — [Q56] `[предл.]`), `full-desc` и `tags-full-desc` — только у агента сервера [UC-04]; логгеры, которые инспектор ставит в ходе добавления (design doc 2.2), стоят ровно для тегов записи (для `unsupported:*` — нет); других изменений на хосте нет [UC-06], [UC-07]; пользователю не показаны разделение записи и заключение куратора [UC-14]."
J_SUM = "`judge-cur-summary` `[предл.]` — `server-name`, `short-desc`, `tags-short-desc`, составленные куратором (критерии — README, «Метрики»; узловые тесты — `curator/summary/*`)"
BREAK = "Разрыв цепочки в любом звене — тест не засчитан; где именно он случился, показывают метрики узлов по журналу и парные node-isolate тесты того же кода сценария."
LOCALIZE = "Метрики узлов по журналу — для локализации разрыва, в доли node-isolate не входят `[предл.]`: "

CHAIN_ADD = """- Форма → инспектор: своими ручками по чек-листу проверяет описание и осматривает сервер; `tags`, `full-desc`, `tags-full-desc` — из результатов ручек и описания из формы; ставит логгеры под выбранные теги (design doc 2.2); `submit` куратору.
- Артефакт инспектора и память системы → куратор: `server-name`, `short-desc`, `tags-short-desc`; сравнение `short-desc` с краткими описаниями уже добавленных серверов.
- Куратор → пользователь: `confirmation` — карточка: `short-desc` и `server-name` на подтверждение [UC-21], `tags-short-desc` — для просмотра [UC-32]; теги и полное описание в карточку не входят.
- Подтверждение → память системы: запись о сервере [AR-29]; название, `conn-ip`, `conn-user`, теги, краткое — в контекст оркестратора; полное — агенту сервера; логгеры, поставленные инспектором, пишут под теги записи."""


def ie(path, title, scen, stand, inp, chain, behav, ref, metrics, basis, data, scenario=None):
    test(P + "/" + path, title, [
        ("Сценарий", scen),
        ("Стенд", stand),
        ("Вход", inp),
        ("Цепочка", chain + "\n\n" + BREAK),
        ("Ожидаемое поведение", behav),
        ("Эталон", ref),
        ("Метрики", metrics),
        ("Основания", basis),
        ("Данные", data),
    ], scenario=scenario)


